import {esc,icon} from './ui.js';
import {importClient} from './import-api.js';
export function mountAi(root){
 let alive=true;const state={orders:[],chatScope:'all',asOf:'—',chatStatus:'AI 服务尚未接入',chatDraft:''};
 const orderOptions=(selected,all)=>`${all?'<option value="all">全部订单</option>':''}${state.orders.map(o=>`<option value="${esc(o.id)}" ${o.id===selected?'selected':''}>${esc(o.id)}</option>`).join('')}`;
function aiPage(){const o=state.orders.find(x=>x.id===state.chatScope);return `<div class="chat-layout"><aside class="panel chat-context"><h2>分析上下文</h2><label for="chat-scope" class="muted">选择订单范围</label><select id="chat-scope" class="control">${orderOptions(state.chatScope,true)}</select><p>对话将关联选中的订单、日期和数据版本，方便后续追溯回答依据。</p><div class="context-line"><span>数据截至</span><strong>${state.asOf}</strong></div><div class="context-line"><span>订单范围</span><strong>${o?'单笔订单':'全部 '+state.orders.length+' 笔'}</strong></div><div class="context-line"><span>数据类型</span><strong>合成演示数据</strong></div><div class="context-line"><span>服务状态</span><strong>未接入</strong></div><div class="help-block">${icon('info')} 接入后，成本与利润由计算服务提供，AI 负责解释数据、列出依据和提出核查建议。</div></aside><section class="panel chat-panel"><div class="chat-center"><div class="ai-orb">${icon('spark')}</div><h2>让订单数据更容易理解</h2><p>从一笔订单开始，了解利润变化与成本偏差。<br>当前为对话界面预览，AI 服务待接入。</p><div class="prompts"><button class="prompt" data-prompt="哪些订单今天需要优先关注？">哪些订单需要优先关注？<span>查看多订单风险与利润偏差</span></button><button class="prompt" data-prompt="这笔订单与预期相比少赚了多少？">与预期相比少赚了多少？<span>理解实际与计划之间的差距</span></button><button class="prompt" data-prompt="利润差距主要体现在哪些成本项目？">利润差距体现在哪些成本？<span>定位材料、人工与能耗偏差</span></button><button class="prompt" data-prompt="还有哪些数据需要补充才能判断原因？">还需要补充哪些数据？<span>识别缺失记录与待核查信息</span></button></div></div><form class="composer" id="chat-form"><div class="chat-status" role="status">${esc(state.chatStatus)}</div><div class="composer-box"><textarea id="chat-input" aria-label="向 AI 提问" placeholder="输入关于订单利润或生产数据的问题…" maxlength="2000">${esc(state.chatDraft)}</textarea><div class="composer-actions"><span>AI 接口待接入 · 当前不会发送数据</span><button class="button primary" type="submit">${icon('send')}发送</button></div></div><p class="footnote">后续回答将展示结论、引用依据和待确认项。模型部署方式由团队进一步确定。</p></form></section></div>`;}

 function render(){if(!alive)return;root.innerHTML=aiPage();root.querySelector('#chat-scope').onchange=e=>{state.chatScope=e.target.value;render();};root.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{state.chatDraft=b.dataset.prompt;render();});root.querySelector('#chat-input').oninput=e=>state.chatDraft=e.target.value;root.querySelector('#chat-form').onsubmit=e=>{e.preventDefault();state.chatStatus='AI 服务尚未接入，当前问题不会发送。';render();};}
 render();importClient.getImportedOrders().then(r=>{state.orders=r.orders;state.asOf=state.orders[0]?.start??'—';render();}).catch(()=>{});return ()=>{alive=false;};
}
